  "r.classic.origin": "Italia → Francia → el mundo", "r.classic.players": "1+ (contra la casa)", "r.classic.time": "unos 30 s por mano",
  "r.classic.facts": "Un sabot de 6–8 barajas|Apuesta a Jugador o Banca|Gana el más cercano a 9|Terceras cartas según reglas fijas",
  "r.classic.hist": "Se dice que viene de un juego italiano del siglo XV; a través del \"chemin de fer\" francés se convirtió en el actual Punto Banco en Sudamérica y Cuba. Llegó a Las Vegas a finales de los años 50 y hoy es la mayor fuente de ingresos de los casinos de Macao.",
  "r.classic.win": "Adivina qué mano, Jugador o Banca, terminará más cerca de 9. El lado ganador cobra; en un Empate las apuestas principales se devuelven.",
  "r.classic.cult": "Se dice que \"baccarat\" viene de la palabra italiana para cero. Famoso por ser el juego de James Bond y, en Asia, por el lento \"squeeze\" de las cartas.",
  "r.classic.p": [
    { t: "Contar", b: "A = 1, 2–9 su valor, 10/J/Q/K = 0. La última cifra de la suma es la mano.", task: "¿Cuánto suman 7 y 8?", ok: "La última cifra de 15: ¡5!", ng: "Quédate solo con la última cifra." },
    { t: "Las figuras valen cero", b: "10, J, Q y K valen 0. La mejor mano es 9.", task: "K y 9 suman…?", ok: "K vale 0: ¡un 9, lo mejor!", ng: "Las figuras cuentan 0." },
    { t: "Naturales", b: "Un 8 o 9 con las dos primeras cartas es un \"natural\": la mano termina sin terceras cartas.", task: "¿Qué pasa aquí?", ok: "El 8 del Jugador es natural: ¡decidido!", ng: "8 y 9 son naturales." },
    { t: "Tercera carta del Jugador", b: "Sin natural, el Jugador roba con 0–5 y se planta con 6–7.", task: "¿Roba el Jugador?", ok: "Un 5: ¡el Jugador roba!", ng: "Con 0–5 roba." },
    { t: "Si el Jugador se planta", b: "Si el Jugador se plantó, la Banca también roba con 0–5 y se planta con 6–7.", task: "¿Roba la Banca?", ok: "¡La Banca con 5 roba!", ng: "Con el Jugador plantado, la Banca roba con 0–5." },
    { t: "Tercera carta de la Banca", b: "Si el Jugador robó, la Banca mira la tercera carta del Jugador. La Banca con 3 solo se planta si es un 8.", task: "¿Roba la Banca?", ok: "La tercera carta es 8: ¡la Banca se planta!", ng: "Banca 3: solo se planta ante un 8." },
    { t: "Pagos", b: "Jugador paga 1 a 1, Banca 0,95 a 1 tras una comisión del 5 %.", task: "Apuestas 100 a la Banca y ganas. ¿Cuánto recibes?", ok: "¡100 + 95 = 195!", ng: "La Banca paga un 5 % menos." },
    { t: "Empates", b: "Totales iguales son Empate. Las apuestas a Jugador y Banca se devuelven; la apuesta al Empate paga 8 a 1.", task: "100 al Jugador, este resultado. ¿Cuánto recibes?", ok: "7 a 7: te devuelven los 100.", ng: "Un empate no es una derrota." },
  ],
