 "r.classic.time": "每局約 30 秒",
 "r.classic.facts": "6–8 副牌的牌靴|押閒或莊|最接近 9 的贏|第三張牌依固定規則",
 "r.classic.hist": "據說源自 15 世紀的義大利遊戲；經由法國的「chemin de fer」，在南美和古巴演變成今日的 Punto Banco。1950 年代末傳到拉斯維加斯，如今是澳門賭場最大的收入來源。",
 "r.classic.win": "猜閒和莊哪一方更接近 9。贏的一方獲得賠付；和局時主注退回。",
 "r.classic.cult": "「Baccarat」據說來自義大利語的「零」。以詹姆士・龐德的遊戲聞名，在亞洲則以慢慢「咪牌」著稱。",
 "r.classic.p": [
  {
   "t": "點數算法",
   "b": "A = 1，2–9 照數字，10/J/Q/K = 0。總和的個位數就是點數。",
   "task": "7 和 8 是幾點？",
   "ok": "15 的個位數：5！",
   "ng": "只留個位數。"
  },
  {
   "t": "人頭牌是零",
   "b": "10、J、Q、K 算 0。最大的牌是 9。",
   "task": "K 和 9 是……？",
   "ok": "K 是 0——9 點，最大！",
   "ng": "人頭牌算 0。"
  },
  {
   "t": "天牌",
   "b": "前兩張是 8 或 9 就是「天牌」：不補第三張牌，這局就結束。",
   "task": "這裡會怎樣？",
   "ok": "閒家 8 是天牌——決定了！",
   "ng": "8 和 9 是天牌。"
  },
  {
   "t": "閒家的第三張牌",
   "b": "沒有天牌時，閒家 0–5 補牌、6–7 停牌。",
   "task": "閒家要補牌嗎？",
   "ok": "5 點——閒家補牌！",
   "ng": "0–5 補牌。"
  },
  {
   "t": "閒家停牌時",
   "b": "閒家停牌時，莊家也是 0–5 補牌、6–7 停牌。",
   "task": "莊家要補牌嗎？",
   "ok": "莊家 5 點補牌！",
   "ng": "閒家停牌時，莊家 0–5 補牌。"
  },
  {
   "t": "莊家的第三張牌",
   "b": "閒家補牌時，莊家看閒家的第三張牌。莊家 3 點只有在那張是 8 時停牌。",
   "task": "莊家要補牌嗎？",
   "ok": "第三張是 8——莊家停牌！",
   "ng": "莊家 3 點：只有 8 時停牌。"
  },
  {
   "t": "賠付",
   "b": "閒賠 1 比 1，莊扣 5% 佣金後賠 0.95 比 1。",
   "task": "你押莊 100 並且贏了。會拿回多少？",
   "ok": "100 + 95 = 195！",
   "ng": "莊少賠 5%。"
  },
  {
   "t": "和局",
   "b": "點數相同是和局。押閒和押莊退回；押和賠 8 比 1。",
   "task": "押閒 100，這個結果。會拿回多少？",
   "ok": "7 比 7——100 退回。",
   "ng": "和局不算輸。"
  }
 ],
