Object.assign(I18N.zh, {"tl.eor": "单张牌的影响（该点数出一张后期望值的变化，%）", "tl.eorHelp": "绿色对下注者有利，红色不利。例如小牌（4、5、6等）出掉后庄的期望值下降、闲上升。但每张牌的影响都非常小。", "tl.hist": "本靴期望值的变化", "tl.histNone": "还没有发牌。每发一局都会记录在这里。", "tl.histRange": "纵轴 {a}% 〜 {b}%", "tl.last": "上一局", "tl.cmp": "各规则的庄家优势", "tl.hour": "玩一小时（约70局）", "tl.hourHelp": "每局下注 {s}、共 {n} 次的平均损失。"});
Object.assign(I18N.ko, {"tl.eor": "카드 1장의 영향(그 숫자가 1장 나왔을 때 기대값 변화, %)", "tl.eorHelp": "초록은 베팅한 사람에게 유리, 빨강은 불리. 예를 들어 작은 숫자(4·5·6 등)가 나오면 뱅커의 기대값은 내려가고 플레이어는 올라갑니다. 그래도 한 장의 차이는 아주 작습니다.", "tl.hist": "이 슈의 기대값 변화", "tl.histNone": "아직 딜하지 않았습니다. 딜할 때마다 여기에 기록됩니다.", "tl.histRange": "세로축 {a}% 〜 {b}%", "tl.last": "직전 판", "tl.cmp": "룰별 하우스 엣지", "tl.hour": "1시간 플레이하면(약 70판)", "tl.hourHelp": "매번 {s}씩 {n}번 베팅했을 때의 평균 손실입니다."});
Object.assign(I18N.es, {"tl.eor": "Efecto de una carta (cambio de la expectativa al salir una carta de ese valor, %)", "tl.eorHelp": "Verde favorece al apostador, rojo lo perjudica. Si salen cartas bajas (4, 5, 6…) baja la expectativa de la Banca y sube la del Jugador, pero cada carta mueve muy poco.", "tl.hist": "Expectativa a lo largo de este zapato", "tl.histNone": "Aún no se ha repartido. Cada mano se registrará aquí.", "tl.histRange": "escala {a}% a {b}%", "tl.last": "La última mano", "tl.cmp": "Ventaja de la casa por reglas", "tl.hour": "Una hora de juego (unas 70 manos)", "tl.hourHelp": "La pérdida media apostando {s} en cada mano, {n} veces."});
Object.assign(I18N.fr, {"tl.eor": "Effet d'une carte (variation de l'espérance quand une carte de cette valeur sort, %)", "tl.eorHelp": "Vert favorise le parieur, rouge le pénalise. Quand les petites cartes (4, 5, 6…) sortent, l'espérance de la Banque baisse et celle du Joueur monte — mais chaque carte ne change presque rien.", "tl.hist": "Espérance au fil de ce sabot", "tl.histNone": "Aucun coup distribué. Chaque coup sera noté ici.", "tl.histRange": "échelle {a} % à {b} %", "tl.last": "Le dernier coup", "tl.cmp": "Avantage de la maison selon les règles", "tl.hour": "Une heure de jeu (environ 70 coups)", "tl.hourHelp": "La perte moyenne en misant {s} à chaque coup, {n} fois."});
Object.assign(I18N.pt, {"tl.eor": "Efeito de uma carta (mudança na expectativa quando sai uma carta desse valor, %)", "tl.eorHelp": "Verde favorece quem aposta, vermelho prejudica. Quando saem cartas baixas (4, 5, 6…), a expectativa da Banca cai e a do Jogador sobe — mas cada carta muda muito pouco.", "tl.hist": "Expectativa ao longo deste sapato", "tl.histNone": "Nenhuma rodada ainda. Cada rodada será registrada aqui.", "tl.histRange": "escala {a}% a {b}%", "tl.last": "A última rodada", "tl.cmp": "Vantagem da casa por regras", "tl.hour": "Uma hora de jogo (cerca de 70 rodadas)", "tl.hourHelp": "A perda média apostando {s} em cada rodada, {n} vezes."});
Object.assign(I18N.de, {"tl.eor": "Wirkung einer Karte (Änderung des Erwartungswerts, wenn eine Karte dieses Werts fehlt, %)", "tl.eorHelp": "Grün hilft dem Spieler, Rot schadet. Fallen kleine Karten (4, 5, 6 …) weg, sinkt der Erwartungswert der Bank und der des Spielers steigt – aber jede Karte bewegt nur sehr wenig.", "tl.hist": "Erwartungswert in diesem Schlitten", "tl.histNone": "Noch keine Runde. Jede Runde wird hier festgehalten.", "tl.histRange": "Skala {a} % bis {b} %", "tl.last": "Die letzte Runde", "tl.cmp": "Hausvorteil je Regel", "tl.hour": "Eine Stunde Spiel (etwa 70 Runden)", "tl.hourHelp": "Der durchschnittliche Verlust bei {s} pro Runde, {n}-mal."});
Object.assign(I18N.hi, {"tl.eor": "एक कार्ड का असर (उस अंक का एक कार्ड निकलने पर अपेक्षित मूल्य में बदलाव, %)", "tl.eorHelp": "हरा दांव लगाने वाले के पक्ष में, लाल विपक्ष में। छोटे कार्ड (4, 5, 6…) निकलने पर बैंकर का अपेक्षित मूल्य घटता है और प्लेयर का बढ़ता है — पर हर कार्ड का असर बहुत छोटा है।", "tl.hist": "इस शू में अपेक्षित मूल्य का बदलाव", "tl.histNone": "अभी कोई राउंड नहीं बँटा। हर राउंड यहाँ दर्ज होगा।", "tl.histRange": "पैमाना {a}% से {b}%", "tl.last": "पिछला राउंड", "tl.cmp": "नियमों के अनुसार हाउस एज", "tl.hour": "एक घंटे का खेल (लगभग 70 राउंड)", "tl.hourHelp": "हर राउंड {s} लगाकर {n} बार खेलने पर औसत नुकसान।"});
