Object.assign(I18N.zh, {"sp.d.P": "闲的点数比庄更接近9即赢。和局时退还本金。", "sp.d.B.classic": "庄的点数比闲更接近9即赢。赢时扣5%佣金，按0.95倍赔付。和局退还。", "sp.d.B.nocomm": "庄的点数比闲更接近9即赢。免佣，1赔1，但庄以6点赢时只赔一半。和局退还。", "sp.d.B.ez": "庄的点数比闲更接近9即赢。免佣，1赔1，但庄以三张牌7点赢时退还。和局退还。", "sp.d.T": "庄闲点数相同即赢。很少出现，所以赔率高。", "sp.d.PP": "闲的前两张牌点数相同（如7和7）即赢，与胜负无关。", "sp.d.BP": "庄的前两张牌点数相同（如K和K）即赢，与胜负无关。", "sp.d.D7": "庄以三张牌合计7点获胜即中。", "sp.d.P8": "闲以三张牌合计8点获胜即中。"});
Object.assign(I18N.ko, {"sp.d.P": "플레이어가 뱅커보다 9에 가까우면 승리. 타이면 베팅금이 돌아옵니다.", "sp.d.B.classic": "뱅커가 플레이어보다 9에 가까우면 승리. 5% 커미션을 빼고 0.95배. 타이면 반환.", "sp.d.B.nocomm": "뱅커가 플레이어보다 9에 가까우면 승리. 커미션 없이 1배, 단 6으로 이기면 절반. 타이면 반환.", "sp.d.B.ez": "뱅커가 플레이어보다 9에 가까우면 승리. 커미션 없이 1배, 단 3장 7로 이기면 반환. 타이면 반환.", "sp.d.T": "플레이어와 뱅커가 같은 숫자면 승리. 드물어서 배당이 큽니다.", "sp.d.PP": "플레이어의 첫 2장이 같은 숫자(예: 7과 7)면 승리. 승패와는 무관.", "sp.d.BP": "뱅커의 첫 2장이 같은 숫자(예: K와 K)면 승리. 승패와는 무관.", "sp.d.D7": "뱅커가 3장으로 합계 7을 만들어 이기면 당첨.", "sp.d.P8": "플레이어가 3장으로 합계 8을 만들어 이기면 당첨."});
Object.assign(I18N.es, {"sp.d.P": "Gana si el Jugador queda más cerca de 9 que la Banca. En empate se devuelve la apuesta.", "sp.d.B.classic": "Gana si la Banca queda más cerca de 9 que el Jugador. Paga 0,95 a 1 tras un 5% de comisión. Empate: se devuelve.", "sp.d.B.nocomm": "Gana si la Banca queda más cerca de 9. Sin comisión, paga 1 a 1, pero la mitad si gana con 6. Empate: se devuelve.", "sp.d.B.ez": "Gana si la Banca queda más cerca de 9. Sin comisión, paga 1 a 1, pero si gana con un 7 de tres cartas se devuelve. Empate: se devuelve.", "sp.d.T": "Gana si Jugador y Banca empatan. Es raro, por eso paga mucho.", "sp.d.PP": "Gana si las dos primeras cartas del Jugador son del mismo valor (p. ej. 7 y 7), gane quien gane.", "sp.d.BP": "Gana si las dos primeras cartas de la Banca son del mismo valor (p. ej. K y K), gane quien gane.", "sp.d.D7": "Gana si la Banca gana con tres cartas que suman 7.", "sp.d.P8": "Gana si el Jugador gana con tres cartas que suman 8."});
Object.assign(I18N.fr, {"sp.d.P": "Gagne si le Joueur finit plus près de 9 que la Banque. En cas d'égalité, la mise est rendue.", "sp.d.B.classic": "Gagne si la Banque finit plus près de 9 que le Joueur. Paie 0,95 contre 1 après 5 % de commission. Égalité : mise rendue.", "sp.d.B.nocomm": "Gagne si la Banque finit plus près de 9. Sans commission, paie 1 contre 1, mais moitié si elle gagne avec 6. Égalité : mise rendue.", "sp.d.B.ez": "Gagne si la Banque finit plus près de 9. Sans commission, paie 1 contre 1, mais un gain avec un 7 en trois cartes est rendu. Égalité : mise rendue.", "sp.d.T": "Gagne si Joueur et Banque sont à égalité. Rare, donc bien payé.", "sp.d.PP": "Gagne si les deux premières cartes du Joueur sont de même valeur (ex. 7 et 7), quel que soit le gagnant.", "sp.d.BP": "Gagne si les deux premières cartes de la Banque sont de même valeur (ex. R et R), quel que soit le gagnant.", "sp.d.D7": "Gagne si la Banque gagne avec trois cartes totalisant 7.", "sp.d.P8": "Gagne si le Joueur gagne avec trois cartes totalisant 8."});
Object.assign(I18N.pt, {"sp.d.P": "Ganha se o Jogador terminar mais perto de 9 que a Banca. No empate, a aposta é devolvida.", "sp.d.B.classic": "Ganha se a Banca terminar mais perto de 9. Paga 0,95 para 1 após 5% de comissão. Empate: devolvida.", "sp.d.B.nocomm": "Ganha se a Banca terminar mais perto de 9. Sem comissão, paga 1 para 1, mas metade se ganhar com 6. Empate: devolvida.", "sp.d.B.ez": "Ganha se a Banca terminar mais perto de 9. Sem comissão, paga 1 para 1, mas vitória com 7 de três cartas é devolvida. Empate: devolvida.", "sp.d.T": "Ganha se Jogador e Banca empatarem. É raro, por isso paga muito.", "sp.d.PP": "Ganha se as duas primeiras cartas do Jogador forem do mesmo valor (ex.: 7 e 7), seja quem for o vencedor.", "sp.d.BP": "Ganha se as duas primeiras cartas da Banca forem do mesmo valor (ex.: K e K), seja quem for o vencedor.", "sp.d.D7": "Ganha se a Banca vencer com três cartas somando 7.", "sp.d.P8": "Ganha se o Jogador vencer com três cartas somando 8."});
Object.assign(I18N.de, {"sp.d.P": "Gewinnt, wenn der Spieler näher an 9 ist als die Bank. Bei Gleichstand gibt es den Einsatz zurück.", "sp.d.B.classic": "Gewinnt, wenn die Bank näher an 9 ist. Zahlt 0,95 zu 1 nach 5 % Kommission. Gleichstand: zurück.", "sp.d.B.nocomm": "Gewinnt, wenn die Bank näher an 9 ist. Ohne Kommission 1 zu 1, aber nur die Hälfte bei einem Sieg mit 6. Gleichstand: zurück.", "sp.d.B.ez": "Gewinnt, wenn die Bank näher an 9 ist. Ohne Kommission 1 zu 1, ein Sieg mit einer Drei-Karten-7 ist aber ein Push. Gleichstand: zurück.", "sp.d.T": "Gewinnt, wenn Spieler und Bank gleich stehen. Selten – darum hohe Auszahlung.", "sp.d.PP": "Gewinnt, wenn die ersten zwei Karten des Spielers den gleichen Rang haben (z. B. 7 und 7) – egal, wer gewinnt.", "sp.d.BP": "Gewinnt, wenn die ersten zwei Karten der Bank den gleichen Rang haben (z. B. K und K) – egal, wer gewinnt.", "sp.d.D7": "Gewinnt, wenn die Bank mit drei Karten und Summe 7 gewinnt.", "sp.d.P8": "Gewinnt, wenn der Spieler mit drei Karten und Summe 8 gewinnt."});
Object.assign(I18N.hi, {"sp.d.P": "अगर प्लेयर बैंकर से 9 के ज़्यादा करीब रहे तो जीत। टाई होने पर दांव लौट आता है।", "sp.d.B.classic": "अगर बैंकर प्लेयर से 9 के ज़्यादा करीब रहे तो जीत। 5% कमीशन काटकर 0.95 गुना। टाई पर दांव वापस।", "sp.d.B.nocomm": "अगर बैंकर 9 के ज़्यादा करीब रहे तो जीत। बिना कमीशन 1 गुना, पर 6 से जीतने पर आधा। टाई पर वापस।", "sp.d.B.ez": "अगर बैंकर 9 के ज़्यादा करीब रहे तो जीत। बिना कमीशन 1 गुना, पर तीन कार्ड के 7 से जीत पर दांव वापस। टाई पर वापस।", "sp.d.T": "अगर प्लेयर और बैंकर का योग बराबर हो तो जीत। कम होता है, इसलिए भुगतान बड़ा है।", "sp.d.PP": "अगर प्लेयर के पहले दो कार्ड एक ही अंक के हों (जैसे 7 और 7) तो जीत — कोई भी जीते।", "sp.d.BP": "अगर बैंकर के पहले दो कार्ड एक ही अंक के हों (जैसे K और K) तो जीत — कोई भी जीते।", "sp.d.D7": "बैंकर तीन कार्ड से 7 बनाकर जीते तो जीत।", "sp.d.P8": "प्लेयर तीन कार्ड से 8 बनाकर जीते तो जीत।"});
Object.assign(I18N.ar, {"sp.d.P": "يربح إذا اقترب اللاعب من 9 أكثر من المصرف. عند التعادل يُعاد الرهان.", "sp.d.B.classic": "يربح إذا اقترب المصرف من 9 أكثر من اللاعب. يدفع 0.95 مقابل 1 بعد عمولة 5%. التعادل: يُعاد.", "sp.d.B.nocomm": "يربح إذا اقترب المصرف من 9 أكثر. بلا عمولة 1 مقابل 1، لكن النصف إذا فاز بـ 6. التعادل: يُعاد.", "sp.d.B.ez": "يربح إذا اقترب المصرف من 9 أكثر. بلا عمولة 1 مقابل 1، لكن الفوز بـ 7 من ثلاث أوراق يُعاد. التعادل: يُعاد.", "sp.d.T": "يربح إذا تساوى اللاعب والمصرف. نادر، لذا يدفع كثيرًا.", "sp.d.PP": "يربح إذا كانت أول ورقتين للاعب من الرتبة نفسها (مثل 7 و7) أيًّا كان الفائز.", "sp.d.BP": "يربح إذا كانت أول ورقتين للمصرف من الرتبة نفسها (مثل K وK) أيًّا كان الفائز.", "sp.d.D7": "يربح إذا فاز المصرف بثلاث أوراق مجموعها 7.", "sp.d.P8": "يربح إذا فاز اللاعب بثلاث أوراق مجموعها 8."});
/* amounts are in dollars */
['zh', 'ko', 'es', 'fr', 'pt', 'de', 'hi', 'ar'].forEach(l => { const x = I18N[l] && I18N[l]['tl.per10k']; if (x) I18N[l]['tl.per10k'] = x.replace(/10[,. ]?000/, '$$10,000'); });
